import {massTasks,magnesiumBalance,atomicMasses,formulaTasks,formulaMass,repeatSets,statistics} from './quant-models.js?v=20261023-physicscomplete01';
import {showLedger,showFormula,showPlot} from './quant-scenes.js?v=20261023-physicscomplete01';
const $=s=>document.querySelector(s),btn=(id,t)=>`<button class="secondary" id="${id}">${t}</button>`;
const input=(id,label,value='',step='any')=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" id="${id}" type="number" step="${step}" value="${value}">`;
const select=(id,label,opts,value='')=>`<label class="field-label" for="${id}">${label}</label><select id="${id}" class="lab-select"><option value="">Choose</option>${opts.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select>`;
export function mountQuantWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.passed??=[];const pass=msg=>{p.widgetDone=true;save();done();feedback(msg);};const again=()=>{save();mountQuantWidget(l,p,root,{save,done,feedback});};
 if(l.widget==='quant-mass'){
 w.task??=0;w.coeff??=[1,1,1];w.answers??={};const i=w.task,t=massTasks[i];w.answers[i]??={mass:'',reason:''};const a=w.answers[i];root.innerHTML='<p>Balance Mg(s) + O₂(g) → MgO(s) using the smallest positive whole coefficients.</p><div class="diagram-inputs">'+['Mg','O₂','MgO'].map((e,j)=>input('magnesiumCoef'+j,'Coefficient '+e,w.coeff[j],'1')).join('')+'</div>'+btn('checkMagnesiumBalance','Check atom conservation')+`<p><b>Mass account ${i+1} / 3</b></p><p>${t.equation}</p><p>${t.text}</p>`+input('massPrediction','Your predicted mass / g',a.mass)+select('massBoundary','Explain this weighed boundary',[['enter','Oxygen enters the initial metal sample'],['leave','CO₂ leaves the initial solid sample'],['closed','All material stays within the weighed boundary']],a.reason)+btn('checkMassLedger','Check and reveal')+btn('nextMassLedger','Next mass account →')+`<p id="massProgress">${w.passed.filter(x=>typeof x==='number').length} / 3 mass accounts correct</p><p class="micro-note">A mathematical account, not a procedure for heating sealed equipment.</p>`;showLedger(t,w.passed.includes(i));w.coeff.forEach((_,j)=>$('#magnesiumCoef'+j).oninput=e=>{w.coeff[j]=Math.max(0,Math.min(8,Math.floor(Number(e.target.value)||0)));save();});const finish=()=>{if(w.passed.length===4)pass('Equation and all three system-boundary accounts are correct.');};$('#checkMagnesiumBalance').onclick=()=>{if(w.coeff.join(',')==='2,1,2'){if(!w.passed.includes('balanced'))w.passed.push('balanced');save();feedback('Balanced: 2Mg(s) + O₂(g) → 2MgO(s), two Mg and two O atoms on each side.');finish();}else feedback(magnesiumBalance(w.coeff)?'Atom counts match. Reduce to the smallest whole coefficients.':'Count Mg and O on both sides. Change coefficients, not the formulae.',true);};$('#massPrediction').oninput=e=>{a.mass=e.target.value;save();};$('#massBoundary').onchange=e=>{a.reason=e.target.value;save();};$('#checkMassLedger').onclick=()=>{if(a.mass!==''&&Math.abs(Number(a.mass)-t.answer)<.001&&a.reason===t.reason){if(!w.passed.includes(i))w.passed.push(i);save();showLedger(t,true);$('#massProgress').textContent=w.passed.filter(x=>typeof x==='number').length+' / 3 mass accounts correct';feedback('Correct. '+t.after+'. Include any gas entering or leaving the boundary.');finish();}else feedback('Account for all the mass and select the matching boundary explanation. Invisible gas still has mass.',true);};$('#nextMassLedger').onclick=()=>{w.task=(i+1)%3;again();};return;
 }
 if(l.widget==='quant-formula'){
 w.task??=0;w.answers??={};const i=w.task,t=formulaTasks[i],els=Object.keys(t.counts);w.answers[i]??={counts:Object.fromEntries(els.map(e=>[e,0])),mr:'',percent:''};const a=w.answers[i];root.innerHTML=`<p><b>Formula ${i+1} / 3: ${t.formula}</b></p><p>Aᵣ values: ${els.map(e=>e+'='+atomicMasses[e]).join(', ')}. Choose atom counts, then calculate Mᵣ and the percentage by mass of <b>${t.target}</b> to 1 decimal place.</p><div class="diagram-inputs">`+els.map(e=>input('formulaCount'+e,e+' atoms',a.counts[e],'1')).join('')+'</div>'+input('formulaMr','Relative formula mass (no unit)',a.mr)+input('formulaPercent',t.target+' by mass / %',a.percent)+btn('checkFormulaAccount','Check counts, mass and percentage')+btn('nextFormulaAccount','Next formula →')+`<p id="formulaProgress">${w.passed.length} / 3 formula accounts correct</p><div class="callout">The displayed atoms are an inventory, not a molecular shape. Brackets multiply every atom inside; coefficients multiply whole formulae.</div>`;showFormula(a.counts,t.formula);els.forEach(e=>$('#formulaCount'+e).oninput=v=>{a.counts[e]=Math.max(0,Math.min(6,Math.floor(Number(v.target.value)||0)));save();showFormula(a.counts,t.formula);});$('#formulaMr').oninput=e=>{a.mr=e.target.value;save();};$('#formulaPercent').oninput=e=>{a.percent=e.target.value;save();};$('#checkFormulaAccount').onclick=()=>{const mr=formulaMass(t.counts),percent=t.counts[t.target]*atomicMasses[t.target]/mr*100;if(els.every(e=>a.counts[e]===t.counts[e])&&a.mr!==''&&Number(a.mr)===mr&&a.percent!==''&&Math.abs(Number(a.percent)-percent)<=.051){if(!w.passed.includes(i))w.passed.push(i);save();$('#formulaProgress').textContent=w.passed.length+' / 3 formula accounts correct';feedback(`Correct: Mᵣ=${mr}; ${t.target} contributes ${t.counts[t.target]*atomicMasses[t.target]}. Percentage=${percent.toFixed(1)}%.`);if(w.passed.length===3)pass('All three atom counts, formula masses and mass percentages are correct.');}else feedback('Count every atom, including bracket multipliers. Sum count×Aᵣ, then divide the chosen element’s whole contribution by Mᵣ and multiply by 100.',true);};$('#nextFormulaAccount').onclick=()=>{w.task=(i+1)%3;again();};return;
 }
 w.task??=0;w.answers??={};const i=w.task,values=repeatSets[i],s=statistics(values);w.answers[i]??={mean:'',range:'',half:''};const a=w.answers[i];root.innerHTML=`<p><b>Repeat set ${i+1} / 3</b></p><p>Readings: ${values.map(v=>v.toFixed(2)).join(', ')} g. Calculate the mean and full range, then use <b>half the range</b> as the requested uncertainty estimate. Answers within 0.001 g are accepted.</p>`+input('measurementMean','Mean / g',a.mean)+input('measurementRange','FULL range / g',a.range)+input('measurementHalf','HALF-range estimate / g',a.half)+btn('checkMeasurement','Check the distribution')+btn('nextMeasurement','Next repeat set →')+`<p id="measurementProgress">${w.passed.filter(x=>typeof x==='number').length} / 3 sets calculated</p>`+select('measurementClaim','Close repeats establish…',[['repeat','Repeatability, but not necessarily accuracy'],['exact','An exactly known true value']],w.claim||'')+btn('checkMeasurementClaim','Check the conclusion');showPlot(values);for(const[k,id]of[['mean','measurementMean'],['range','measurementRange'],['half','measurementHalf']])$('#'+id).oninput=e=>{a[k]=e.target.value;save();};const finish=()=>{if(w.passed.length===4)pass('All three distributions calculated and the evidence limitation identified.');};$('#checkMeasurement').onclick=()=>{if(['mean','range','half'].every(k=>a[k]!==''&&Math.abs(Number(a[k])-s[k])<=.001)){if(!w.passed.includes(i))w.passed.push(i);save();$('#measurementProgress').textContent=w.passed.filter(x=>typeof x==='number').length+' / 3 sets calculated';feedback(`Mean=${s.mean.toFixed(2)} g; full range=${s.range.toFixed(2)} g; half-range=±${s.half.toFixed(2)} g.`);finish();}else feedback('Mean=sum÷number of readings. Full range=max−min. Half-range is half that spread; it is not the full range.',true);};$('#nextMeasurement').onclick=()=>{w.task=(i+1)%3;again();};$('#measurementClaim').onchange=e=>{w.claim=e.target.value;save();};$('#checkMeasurementClaim').onclick=()=>{if(w.claim==='repeat'){if(!w.passed.includes('claim'))w.passed.push('claim');save();feedback('Correct: systematic errors can shift all the readings together.');finish();}else feedback('Close repeats show low variation, but do not rule out a systematic offset.',true);};
}
